import React, { createContext, useState } from "react";
import { RouterComponents } from "../../models/router-components";
import { MainLayout } from "../../layouts";
import { FaqContainer, QuestionsContainer, ReputationContainer, RulesContainer } from "../../containers";

const navigationLocalKey = 'asdw132ed';

const components: { [k in RouterComponents]: JSX.Element } = {
    rules: <RulesContainer />,
    reputation: <ReputationContainer />,
    questions: <QuestionsContainer />,
    faq: <FaqContainer />,
};

export const RouterContext = createContext<null | {
    setCurrentComponents: (e: RouterComponents) => void;
}>(null);

export default function Router() {
    const [currentComponents, setCurrentComponents] =
        useState<RouterComponents>(() => {
            const formLocalStore = localStorage.getItem(navigationLocalKey) as RouterComponents;
            if (formLocalStore) return formLocalStore
            return 'rules'
        });

    function toggleCurrentComponents(e: RouterComponents) {
        localStorage.setItem(navigationLocalKey, e)
        setCurrentComponents(e)
    }
    return (
        <RouterContext.Provider value={{ setCurrentComponents: toggleCurrentComponents }}>
            <MainLayout>{components[currentComponents]}</MainLayout>
        </RouterContext.Provider>
    );
}
