import { useContext, useState } from "react";
import { Menu as IconMenu } from "@mui/icons-material";
import { Drawer, Fab, List, ListItemButton, ListItemText, ListSubheader, Typography } from "@mui/material";
import { RouterComponents } from "../../models/router-components";
import { RouterContext } from "../router";
import { navigationMenu } from "../../constants/navigation";
import logo from '../../imgs/logo.png'
import AppBar from '@mui/material/AppBar';
import Box from '@mui/material/Box';
import Toolbar from '@mui/material/Toolbar';

import Container from '@mui/material/Container';
import Button from '@mui/material/Button';

const fabStyle = {
    position: 'fixed',
    bottom: 16,
    right: 16,
    zIndex: 99999,
};

export default function Navigation() {
    const router = useContext(RouterContext);
    const [showNavigation, setShowNavigation] = useState(false)

    function toggleShowNavigation() {
        setShowNavigation(prev => !prev)
    }

    function toggleRoute(e: RouterComponents) {
        return () => {
            setShowNavigation(false)
            router?.setCurrentComponents(e);
        };
    }

    function toggleCloseNavigation() {
        setShowNavigation(false)
    }
    return (
        <>
            <Fab sx={(theme) => ({
                ...fabStyle,
                display: {
                    md: 'none'
                }
            })}
                color="primary" aria-label="add" onClick={toggleShowNavigation}>
                <IconMenu />
            </Fab>


            <Drawer sx={(theme) => ({
                ...fabStyle,
                [theme.breakpoints.up('md')]: {
                    display: 'none'
                }
            })}
                open={showNavigation}
                onClose={toggleCloseNavigation} anchor='bottom'>
                <List
                    sx={{ width: '100%', }}
                    component="nav"
                    aria-labelledby="nested-list-subheader"
                    subheader={
                        <ListSubheader
                            component="div" id="nested-list-subheader" sx={{ borderBottom: '2px solid #d1d1d1' }}>
                            <Typography component={'h2'} sx={{ fontSize: 18, margin: '20px 0' }}>
                                Навигация:
                            </Typography>
                        </ListSubheader>
                    }
                >
                    {
                        navigationMenu.map(navItem => (
                            <ListItemButton
                                onClick={toggleRoute(navItem.route)}
                            >
                                <ListItemText primary={navItem.text} />
                            </ListItemButton>
                        ))
                    }
                </List >
            </Drawer >
            <DesktopNavigation />
        </>

    );
}


function DesktopNavigation() {
    const router = useContext(RouterContext);
    function toggleRoute(e: RouterComponents) {
        return () => {
            router?.setCurrentComponents(e);
        };
    }
    return (
        <AppBar position="static">
            <Container maxWidth="xl">
                <Toolbar disableGutters>
                    <Logo size={70} />
                    <Box sx={{ flexGrow: 1, display: { xs: 'none', md: 'flex' } }}>
                        {navigationMenu.map((item) => (
                            <Button
                                onClick={toggleRoute(item.route)}
                                key={item.id}
                                sx={{ my: 2, color: 'white', display: 'block' }}
                            >
                                {item.text}
                            </Button>
                        ))}
                    </Box>
                </Toolbar>
            </Container>
        </AppBar>
    )
}



function Logo({ size = 200 }: { size?: number }) {
    return (
        <>
            <img
                style={{
                    display: 'block', width: `${size}px`, margin: '10px auto'
                }}
                width={size}
                height={size}
                src={logo}
                alt={'Mercenaries logo'}
                loading="lazy"
            />
        </>
    )
}